# 0x4dfb24 (printf's value formatter): the printf state, the buffer and the argument pointer's home
# are pool objects; the state's letter (+0x15), flags (+0x1e, +0x1f), width (+4) and precision (+8)
# take every value the routine tells apart, the arguments (+0x40 of an object) are zeros, signs,
# words, a far selector and string pointers. The string lengths (0x4df884, 0x4df8a8) and wctomb
# (0x4e62e0) are drawn, the multibyte flag (0x5c8950) and the lead byte table entries of the
# frame bytes wctomb would have written (0x41, 0x81) too. The 64-bit value 0x4e63b0 converts is logged.
export VERTRIX_HANDLE_REGISTERS=eax,edx,ebx
export VERTRIX_FRAME_BYTES="0x41,0x81"
